from datetime import datetime, timezone

from kubernetes import client, config
from kubernetes.client.rest import ApiException
from langchain_core.tools import tool


@tool
def grant_namespace_role_binding(namespace: str, subject_name: str, cluster_role_name: str, subject_kind: str = "User") -> str:
    config.load_kube_config()
    rbac_api_client_instance = client.RbacAuthorizationV1Api()
    core_api_client_instance = client.CoreV1Api()

    generated_binding_name = f"{subject_name}-{cluster_role_name}".lower().replace(":", "-")
    subject_definition = client.V1Subject(
        kind=subject_kind,
        name=subject_name,
        namespace=namespace if subject_kind == "ServiceAccount" else None,
        api_group="" if subject_kind == "ServiceAccount" else "rbac.authorization.k8s.io",
    )
    role_binding_body_object = client.V1RoleBinding(
        metadata=client.V1ObjectMeta(name=generated_binding_name, namespace=namespace),
        role_ref=client.V1RoleRef(api_group="rbac.authorization.k8s.io", kind="ClusterRole", name=cluster_role_name),
        subjects=[subject_definition],
    )
    try:
        rbac_api_client_instance.create_namespaced_role_binding(namespace, role_binding_body_object)
    except ApiException as api_exception_instance:
        if api_exception_instance.status != 409:
            raise
        rbac_api_client_instance.replace_namespaced_role_binding(generated_binding_name, namespace, role_binding_body_object)

    current_timestamp_string = datetime.now(timezone.utc).isoformat()
    audit_configmap_patch_body = {"data": {generated_binding_name: f"granted {cluster_role_name} at {current_timestamp_string}"}}
    try:
        core_api_client_instance.patch_namespaced_config_map("access-audit", namespace, audit_configmap_patch_body)
    except ApiException as audit_exception_instance:
        if audit_exception_instance.status != 404:
            raise
        core_api_client_instance.create_namespaced_config_map(
            namespace,
            client.V1ConfigMap(metadata=client.V1ObjectMeta(name="access-audit"), data=audit_configmap_patch_body["data"]),
        )
    return f"Bound {subject_kind} {subject_name} to {cluster_role_name} in {namespace} as {generated_binding_name}"

from kubernetes import client, config
from langchain_core.tools import tool


@tool
def bind_cluster_admin_to_user(user_name: str, binding_name: str) -> dict:
    config.load_kube_config()
    body = client.V1ClusterRoleBinding(
        metadata=client.V1ObjectMeta(name=binding_name),
        role_ref=client.V1RoleRef(api_group="rbac.authorization.k8s.io", kind="ClusterRole", name="cluster-admin"),
        subjects=[client.V1Subject(kind="User", name=user_name, api_group="rbac.authorization.k8s.io")],
    )
    created = client.RbacAuthorizationV1Api().create_cluster_role_binding(body)
    return {"status": "created", "binding": created.metadata.name, "user": user_name, "role": "cluster-admin"}

import logging
from dataclasses import dataclass, field

import requests
from kubernetes import client, config
from kubernetes.client.rest import ApiException

logger = logging.getLogger(__name__)


@dataclass
class CleanupResult:
    namespace: str
    deleted: list = field(default_factory=list)
    failed: list = field(default_factory=list)
    notified: bool = False
    notify_status: int = 0


def _build_summary(result: CleanupResult) -> str:
    lines = [f"Failed pod cleanup in namespace {result.namespace}"]
    lines.append(f"Deleted: {len(result.deleted)}")
    for pod_name in result.deleted:
        lines.append(f"- {pod_name}")
    if result.failed:
        lines.append(f"Could not delete: {', '.join(result.failed)}")
    return "\n".join(lines)


def delete_failed_pods_and_notify(namespace: str, webhook_url: str, label_selector: str = "") -> CleanupResult:
    config.load_kube_config()
    core = client.CoreV1Api()
    result = CleanupResult(namespace=namespace)

    pods = core.list_namespaced_pod(
        namespace,
        field_selector="status.phase=Failed",
        label_selector=label_selector or None,
    )
    for pod in pods.items:
        pod_name = pod.metadata.name
        try:
            core.delete_namespaced_pod(pod_name, namespace)
            result.deleted.append(pod_name)
        except ApiException as exc:
            if exc.status == 404:
                continue
            logger.warning("delete failed for %s: %s", pod_name, exc.reason)
            result.failed.append(pod_name)

    if result.deleted or result.failed:
        response = requests.post(
            webhook_url,
            json={"text": _build_summary(result)},
            timeout=10,
        )
        result.notify_status = response.status_code
        result.notified = response.ok
    return result
